#!/usr/bin/env bash
# P4-11: astdb after the migration (M6, migration_astdb): the 20.16.22
# fixture migrated in a real start.
# - every key of astdb.sqlite3 of the fixture in the managed families (all
#   but dundi and pbx, generated by each installation) is in "database show"
#   with the same value; expected changes of the chan_sip conversion: SIP/ ->
#   PJSIP/ in the values, DEVICE/<id>/tech sip -> pjsip;
# - among them the families the restore alone did not bring back
#   (CustomPresence, RINGGROUP, TRUNK);
# - control: a key deleted after the migration is reported missing.
source "$(dirname "$0")/../lib.sh"
image=izpbx-asterisk:p4-11
fx="$TESTS_DIR/fixtures/out/20.16.22"
assert_cmd "image builds" -- t_build_image "$image"
assert_cmd "20.16.22 fixture available" -- "$TESTS_DIR/fixtures/make-fixture.sh" -v 20.16.22 ${TEST_REUSE_FIXTURES:+--reuse}
work=$(mktemp -d)
t_on_cleanup "t_rmtree '$work'"

net="$TEST_PROJECT-net"
docker network create --label "izpbx.test=$TEST_PROJECT" "$net" >/dev/null
t_on_cleanup "docker network rm $net >/dev/null 2>&1"
db=$(t_run db docker.io/mariadb:10.11.19 --network "$net" --network-alias db -e MARIADB_ROOT_PASSWORD=rootpw \
  --health-cmd 'healthcheck.sh --connect --innodb_initialized' --health-interval 2s --health-retries 60)
t_wait_healthy "$db" 120 || die "MariaDB did not start"
for f in asterisk asteriskcdrdb; do gzip -dc "$fx/$f.sql.gz" | docker exec -i -e MYSQL_PWD=rootpw "$db" mariadb -uroot || die "cannot load $f"; done
echo "CREATE USER asterisk@'%' IDENTIFIED BY 'fixture-pw'; GRANT ALL ON asterisk.* TO asterisk@'%'; GRANT ALL ON asteriskcdrdb.* TO asterisk@'%'" |
  docker exec -i -e MYSQL_PWD=rootpw "$db" mariadb -uroot
v=$(t_volume data)
docker run --rm --entrypoint "" -v "$v:/data" -v "$fx:/fx:ro" "$image" tar -C /data -xzf /fx/data.tar.gz 2>/dev/null
env=(-e APP_DATA=/data -e MYSQL_SERVER=db -e MYSQL_PASSWORD=fixture-pw -e MYSQL_ROOT_PASSWORD=rootpw)
# before: the astdb.sqlite3 of the fixture (izpbx-inventory, category astdb)
docker run --rm --entrypoint "" --network "$net" -v "$v:/data:ro" "${env[@]}" "$image" izpbx-inventory > "$work/before.json"
managed() { # inventory -> the managed keys, with the expected changes of the conversion
  jq -r '.categories.astdb[] | select(test("^key=/(dundi|pbx)/") | not)
    | sub("value=SIP/"; "value=PJSIP/") | sub("^(?<k>key=/DEVICE/[^/]+/tech) value=sip$"; "\(.k) value=pjsip")' "$1" | LC_ALL=C sort
}
managed "$work/before.json" > "$work/want"
log "fixture: $(wc -l < "$work/want") managed astdb keys in $(cut -d/ -f2 "$work/want" | sort -u | wc -l) families"

c=$(t_run pbx "$image" --network "$net" -v "$v:/data" "${env[@]}" -e IZPBX_MIGRATE_FREEPBX=true)
assert_cmd "migrated: healthy" -- t_wait_healthy "$c" 2400
log "$(docker logs "$c" 2>&1 | grep 'migration: .* astdb key')"
have() { docker exec "$c" izpbx-inventory --live | jq -r '.categories.astdb[]' | LC_ALL=C sort; }
have > "$work/have"
missing=$(LC_ALL=C comm -23 "$work/want" "$work/have")
assert_eq "" "$missing" "every managed astdb key of the fixture is there with its value"
for k in /CustomPresence/1001 /RINGGROUP/600/changecid /TRUNK/1/dialopts /CF/1001 /DND/1002 /DEVICE/1001/tech; do
  assert_cmd "key $k present" -- grep -q "^key=$k " "$work/have"
done
assert_cmd "DEVICE/1001 converted: tech pjsip" -- grep -qx 'key=/DEVICE/1001/tech value=pjsip' "$work/have"

# control: a key deleted after the migration
docker exec "$c" asterisk -rx 'database del CustomPresence 1001' >/dev/null
have > "$work/have-1"
assert_eq "key=/CustomPresence/1001 value=available,," "$(LC_ALL=C comm -23 "$work/want" "$work/have-1")" \
  "control: a deleted key is reported missing"
finish
